import type { Metadata } from 'next'
import { siteDescription, siteName, siteTagline } from '@/lib/site'

/** Default link-preview image, generated by src/app/opengraph-image.tsx. */
export const shareImage = { url: '/opengraph-image', width: 1200, height: 630, alt: `${siteName} — ${siteTagline}` }

/** The full title a page shows in the tab, as the root title template renders it. */
const fullTitle = (title: Metadata['title']): string => {
  if (typeof title === 'string') return `${title} | ${siteName}`
  if (title && typeof title === 'object' && 'absolute' in title && title.absolute) return title.absolute
  return `${siteName} — ${siteTagline}`
}

/**
 * Completes a page's social-sharing metadata from its own title, description
 * and canonical path. Next.js merges metadata shallowly: a page without
 * openGraph inherits the homepage's title, description and URL wholesale, and
 * a page with one loses siteName, locale and the preview image. Fields the page
 * sets itself win.
 */
export function withSharing(meta: Metadata): Metadata {
  const title = fullTitle(meta.title)
  const description = meta.description ?? siteDescription
  const canonical = meta.alternates?.canonical
  const url = typeof canonical === 'string' || canonical instanceof URL ? canonical : undefined
  const own = (meta.openGraph ?? {}) as Record<string, unknown>

  return {
    ...meta,
    openGraph: {
      type: 'website',
      siteName,
      locale: 'en_GB',
      title,
      description,
      ...(url ? { url } : {}),
      images: [shareImage],
      ...own,
    } as Metadata['openGraph'],
    twitter: {
      card: 'summary_large_image',
      title: typeof own.title === 'string' ? own.title : title,
      description: typeof own.description === 'string' ? own.description : description,
      images: [shareImage.url],
      ...meta.twitter,
    } as Metadata['twitter'],
  }
}
